  1	// src/lib/plattform/backend/demo/sicherheit.js
  2	//
  3	// Login, Sicherheit & Konto im Demo-Backend – Referenz für die Frappe-App (plattform/api/sicherheit.py).
  4	// Vertrag: docs/API.md, Abschnitt „sicherheit“.
  5	//
  6	//   db.sitzungen      { id S-…, nutzerId, version, erstelltAm, ablauf, letzteAktivitaet, ipGrob, ort, userAgent, geraet,
  7	//                       mobil, geraetId, methode, zweiFaktor, organisationId, widerrufenAm }
  8	//   db.geraete        { id G-…, nutzerId, hash (SHA-256 des Geräte-Cookies), label, ersteAnmeldung, letzteAnmeldung,
  9	//                       vertrautBis (2FA „Gerät 30 Tage merken“), zweiFaktorVersion }
 10	//   db.anmeldungen    { id AN-…, nutzerId, email, am, ok, methode, grund, ipGrob, ort, geraet }  (Historie, auch Fehlversuche)
 11	//   db.zweiFaktor     { nutzerId, aktiv, geheimnis (AES-GCM), ausstehend, ausstehendAm, letzterSchritt, codes [SHA-256], aktiviertAm, version }
 12	//   db.anmeldeSperren { <email>: { fehl, bis, zuletzt } }  – Kontosperre mit exponentiellem Backoff
 13	//   db.einstellungen  { zweiFaktorPflicht: [rollen] }       – zusätzlich Umgebungsvariable PLATTFORM_2FA_PFLICHT
 14	//
 15	// Sitzungen: Das signierte Cookie trägt die Sitzungskennung; gültig nur, solange der Eintrag besteht, nicht
 16	// widerrufen/abgelaufen ist und seine Version der Sitzungsversion des Kontos entspricht.
 17	
 18	import { PlattformFehler, konflikt, nichtGefunden, ungueltig, verboten } from "../../fehler";
 19	import * as v from "../../validierung";
 20	import { ALLE_ROLLEN_IDS } from "../../konstanten";
 21	import { geraetAusUserAgent, ipGrob, ortGrob } from "../../geraet";
 22	import {
 23	  codeHash, codesErzeugen, entschluesseln, geheimnisErzeugen, istWiederherstellungscode, otpauthUri, totpPruefen, verschluesseln,
 24	} from "../../totp";
 25	import { komfortBereinigen, teamRolleLabel } from "../../organisation";
 26	import { passwortPruefen } from "../../server/passwort";
 27	import { SITZUNG_DAUER_S } from "../../sitzung";
 28	import { jetzt, neueId, sha256, zufallsToken } from "./hilfen";
 29	import { aendern, lesen } from "./speicher";
 30	import { internSicherheit } from "../demo";
 31	import { orgSammlungen, orgSeed, organisationenVon } from "./organisation";
 32	
 33	export const SPERRE = { schwelle: 5, basisSekunden: 30, maxSekunden: 3600 };
 34	export const MAGIC_LINK_MINUTEN = 15;
 35	export const GERAET_MERKEN_TAGE = 30;
 36	const AKTIVITAET_MS = 60e3;
 37	const EINRICHTUNG_MINUTEN = 30;
 38	
 39	// ================================================================ Helfer
 40	
 41	function sammlungen(db) {
 42	  db.sitzungen ||= [];
 43	  db.geraete ||= [];
 44	  db.anmeldungen ||= [];
 45	  db.zweiFaktor ||= [];
 46	  db.anmeldeSperren ||= {};
 47	  db.einstellungen ||= {};
 48	  db.tokens ||= [];
 49	  db.demoLinks ||= [];
 50	  orgSammlungen(db);
 51	  return db;
 52	}
 53	
 54	const nutzerById = (db, id) => db.nutzer.find((u) => u.id === id) || null;
 55	const zf = (db, nutzerId) => (db.zweiFaktor || []).find((z) => z.nutzerId === nutzerId) || null;
 56	const nameVon = (u) => [u?.vorname, u?.nachname].filter(Boolean).join(" ");
 57	const nichtAngemeldet = () => new PlattformFehler(401, "Bitte melden Sie sich an.");
 58	
 59	function adminNoetig(n) {
 60	  if (!n) throw nichtAngemeldet();
 61	  if (!n.rollen?.includes("admin")) throw verboten("Nur für das Backoffice.");
 62	}
 63	
 64	/** Rollen mit Pflicht zur Zwei-Faktor-Anmeldung (Einstellung im Backoffice ∪ PLATTFORM_2FA_PFLICHT) */
 65	export function pflichtRollen(db) {
 66	  const env = String(process.env.PLATTFORM_2FA_PFLICHT || "").split(",").map((s) => s.trim()).filter((s) => ALLE_ROLLEN_IDS.includes(s));
 67	  return [...new Set([...(db.einstellungen?.zweiFaktorPflicht || []), ...env])];
 68	}
 69	const pflichtFuer = (db, u) => pflichtRollen(db).some((r) => u?.rollen?.includes(r));
 70	
 71	/** Sicherheitsmeldung: Glocke + E-Mail (immer, unabhängig von den Benachrichtigungs-Einstellungen) */
 72	function sicherheitMelden(db, u, { titel, text, betreff, mailText, glocke = true }) {
 73	  if (!u) return;
 74	  if (glocke) internSicherheit.benachrichtigen(db, u, { art: "sicherheit", titel, text, link: "/portal/sicherheit", objektArt: "nutzer", objektId: u.id }, { mail: false });
 75	  internSicherheit.postausgangAnlegen(db, {
 76	    an: u.email, anName: nameVon(u), nutzerId: u.id, art: "sicherheit", betreff, text: mailText || text, link: "/portal/sicherheit", linkText: "Sicherheit prüfen",
 77	    hinweis: "Das waren nicht Sie? Ändern Sie sofort Ihr Passwort und beenden Sie unter „Sicherheit“ alle Sitzungen.",
 78	  });
 79	}
 80	
 81	function historie(db, { nutzer, email, ok, methode, grund = "", ip, userAgent, land }) {
 82	  const g = geraetAusUserAgent(userAgent);
 83	  db.anmeldungen.push({ id: neueId("AN"), nutzerId: nutzer?.id || null, email: email || nutzer?.email || "", am: jetzt(), ok, methode, grund, ipGrob: ipGrob(ip), ort: ortGrob(ip, land), geraet: g.label });
 84	  if (db.anmeldungen.length > 5000) db.anmeldungen.splice(0, db.anmeldungen.length - 5000);
 85	}
 86	
 87	// ================================================================ Kontosperre (exponentieller Backoff)
 88	
 89	/** Wartezeit in Sekunden nach `fehl` Fehlversuchen (0 = keine Sperre) */
 90	export function sperrDauer(fehl) {
 91	  if (fehl < SPERRE.schwelle) return 0;
 92	  return Math.min(SPERRE.maxSekunden, SPERRE.basisSekunden * 2 ** (fehl - SPERRE.schwelle));
 93	}
 94	
 95	const sperrText = (sek) => {
 96	  const min = Math.ceil(sek / 60);
 97	  return `Zu viele fehlgeschlagene Anmeldeversuche. Das Konto ist vorübergehend gesperrt – bitte versuchen Sie es in ${sek < 60 ? `${sek} Sekunden` : `${min} Minute${min === 1 ? "" : "n"}`} erneut oder melden Sie sich per E-Mail-Link an.`;
 98	};
 99	
100	/** Wirft 429 (code „gesperrt“), solange die E-Mail-Adresse gesperrt ist */
101	export function sperrePruefen(db, email) {
102	  const s = db.anmeldeSperren?.[email];
103	  if (!s?.bis) return;
104	  const rest = Math.ceil((new Date(s.bis).getTime() - Date.now()) / 1000);
105	  if (rest > 0) throw new PlattformFehler(429, sperrText(rest), "gesperrt");
106	}
107	
108	/** Fehlversuch zählen (Passwort oder 2FA-Code) – ab der Schwelle wächst die Sperre exponentiell */
109	export function fehlversuchBuchen(db, { email, nutzer, ip, userAgent, land, grund }) {
110	  sammlungen(db);
111	  if (email) {
112	    const s = db.anmeldeSperren[email] || { fehl: 0, bis: null };
113	    s.fehl += 1;
114	    s.zuletzt = jetzt();
115	    const dauer = sperrDauer(s.fehl);
116	    s.bis = dauer ? new Date(Date.now() + dauer * 1000).toISOString() : null;
117	    db.anmeldeSperren[email] = s;
118	    const schluessel = Object.keys(db.anmeldeSperren);
119	    if (schluessel.length > 2000) {
120	      schluessel.sort((a, b) => String(db.anmeldeSperren[a].zuletzt).localeCompare(String(db.anmeldeSperren[b].zuletzt)));
121	      for (const k of schluessel.slice(0, schluessel.length - 2000)) delete db.anmeldeSperren[k];
122	    }
123	    if (nutzer && dauer && s.fehl === SPERRE.schwelle) {
124	      sicherheitMelden(db, nutzer, {
125	        titel: "Konto vorübergehend gesperrt",
126	        text: `${SPERRE.schwelle} fehlgeschlagene Anmeldeversuche – die Anmeldung ist kurz gesperrt.`,
127	        betreff: "Mehrere fehlgeschlagene Anmeldeversuche – ÖkoInvest",
128	        mailText: `Für Ihr Konto gab es ${SPERRE.schwelle} fehlgeschlagene Anmeldeversuche. Die Anmeldung ist deshalb vorübergehend gesperrt; jede weitere Fehleingabe verlängert die Sperre. Über den E-Mail-Link auf der Anmeldeseite kommen Sie jederzeit in Ihr Konto.`,
129	      });
130	    }
131	  }
132	  if (nutzer) historie(db, { nutzer, email, ok: false, methode: grund === "2fa" ? "zwei-faktor" : "passwort", grund, ip, userAgent, land });
133	}
134	
135	// ================================================================ Sitzung (von nutzerFuerSitzung genutzt)
136	
137	/** Nutzer um Sitzung, Organisation, 2FA-Status und Komfort ergänzen */
138	export function nutzerAnreichern(db, u, s = null) {
139	  sammlungen(db);
140	  const orgs = organisationenVon(db, u.id);
141	  const org = s?.organisationId ? orgs.find((o) => o.id === s.organisationId) || null : null;
142	  const z = zf(db, u.id);
143	  const pflicht = pflichtFuer(db, u);
144	  const out = {
145	    ...u,
146	    sitzung: s ? { id: s.id, organisationId: org?.id || null, zweiFaktor: !!s.zweiFaktor } : null,
147	    organisation: org,
148	    organisationen: orgs,
149	    zweiFaktorAktiv: !!z?.aktiv,
150	    zweiFaktorPflicht: pflicht,
151	    zweiFaktorPflichtOffen: pflicht && !z?.aktiv,
152	    komfort: komfortBereinigen(u.komfort || {}),
153	  };
154	  if (org) {
155	    // Im Organisationskontext gilt das Team-Suchprofil
156	    out.suchprofilPersoenlich = u.suchprofil || null;
157	    out.suchprofil = db.organisationen.find((o) => o.id === org.id)?.suchprofil || null;
158	  }
159	  return out;
160	}
161	
162	function sitzungGueltig(s, u) {
163	  return !!s && s.nutzerId === u.id && !s.widerrufenAm && new Date(s.ablauf) > new Date() && (s.version || 0) === (u.sitzungVersion || 0);
164	}
165	
166	/**
167	 * Sitzung prüfen und Nutzer anreichern. Ohne Sitzungskennung (Token aus der Zeit vor den Sitzungslisten)
168	 * gilt nur die Sitzungsversion. Letzte Aktivität wird höchstens einmal pro Minute geschrieben.
169	 */
170	export async function sitzungNutzer(db, u, { sitzungId } = {}) {
171	  sammlungen(db);
172	  if (!sitzungId) return nutzerAnreichern(db, u, null);
173	  const s = db.sitzungen.find((x) => x.id === sitzungId);
174	  if (!sitzungGueltig(s, u)) return null;
175	  if (Date.now() - new Date(s.letzteAktivitaet).getTime() > AKTIVITAET_MS) {
176	    await aendern((d) => {
177	      const x = (d.sitzungen || []).find((y) => y.id === sitzungId);
178	      if (x) x.letzteAktivitaet = jetzt();
179	    }).catch(() => {});
180	  }
181	  return nutzerAnreichern(db, u, s);
182	}
183	
184	/** 2FA-Status für das Ergebnis von anmelden (steuert den zweiten Schritt) */
185	export const mitZweiFaktor = (db, u) => ({ ...u, zweiFaktorAktiv: !!zf(sammlungen(db), u.id)?.aktiv });
186	
187	// ================================================================ Operationen: Sitzungen & Geräte
188	
189	/**
190	 * Neue Sitzung nach vollständiger Anmeldung (Passwort/E-Mail-Link + ggf. 2FA). Setzt die Sperre zurück,
191	 * schreibt die Historie, erkennt neue Geräte (Benachrichtigung + E-Mail) und merkt das Gerät optional 30 Tage.
192	 * Liefert { sitzung: {id}, geraetToken (nur wenn neu erzeugt), neuesGeraet }.
193	 */
194	export async function sitzungAnlegen(n, { ip = "", userAgent = "", land = "", methode = "passwort", zweiFaktor = false, geraetToken = "", geraetMerken = false, ersetzt = null } = {}) {
195	  if (!n) throw nichtAngemeldet();
196	  return aendern((db) => {
197	    sammlungen(db);
198	    orgSeed(db);
199	    const u = nutzerById(db, n.id);
200	    if (!u || !u.aktiv) throw nichtAngemeldet();
201	    delete db.anmeldeSperren[u.email];
202	    const g = geraetAusUserAgent(userAgent);
203	    const grob = ipGrob(ip);
204	    const ort = ortGrob(ip, land);
205	    const tokenOk = /^[A-Za-z0-9_-]{30,100}$/.test(String(geraetToken || ""));
206	    let geraet = tokenOk ? db.geraete.find((x) => x.nutzerId === u.id && x.hash === sha256(geraetToken)) : null;
207	    const bekannt = !!geraet || db.anmeldungen.some((a) => a.nutzerId === u.id && a.ok && a.geraet === g.label && a.ipGrob === grob);
208	    let neuesToken = null;
209	    if (!geraet) {
210	      const token = tokenOk ? geraetToken : zufallsToken();
211	      if (!tokenOk) neuesToken = token;
212	      geraet = { id: neueId("G"), nutzerId: u.id, hash: sha256(token), label: g.label, mobil: g.mobil, ersteAnmeldung: jetzt(), letzteAnmeldung: jetzt(), vertrautBis: null, zweiFaktorVersion: null };
213	      db.geraete.push(geraet);
214	    }
215	    geraet.letzteAnmeldung = jetzt();
216	    geraet.label = g.label;
217	    const z = zf(db, u.id);
218	    if (geraetMerken && zweiFaktor && z?.aktiv) {
219	      geraet.vertrautBis = new Date(Date.now() + GERAET_MERKEN_TAGE * 86400e3).toISOString();
220	      geraet.zweiFaktorVersion = z.version;
221	    }
222	
223	    // Sitzungsrotation: eine ersetzte Sitzung (z. B. nach 2FA-Einrichtung) wird beendet, Kontext bleibt
224	    const alt = ersetzt ? db.sitzungen.find((x) => x.id === ersetzt && x.nutzerId === u.id) : null;
225	    if (alt && !alt.widerrufenAm) {
226	      alt.widerrufenAm = jetzt();
227	      alt.widerrufenGrund = "rotation";
228	    }
229	    const s = {
230	      id: neueId("S", 10), nutzerId: u.id, version: u.sitzungVersion || 0, erstelltAm: jetzt(),
231	      ablauf: new Date(Date.now() + SITZUNG_DAUER_S * 1000).toISOString(), letzteAktivitaet: jetzt(),
232	      ipGrob: grob, ort, userAgent: v.text(userAgent, 300), geraet: g.label, mobil: g.mobil, geraetId: geraet.id,
233	      methode, zweiFaktor: !!zweiFaktor, organisationId: alt?.organisationId || null, widerrufenAm: null,
234	    };
235	    db.sitzungen.push(s);
236	    // Aufräumen: abgelaufene/widerrufene Einträge nach 30 Tagen, höchstens 30 aktive Sitzungen je Konto
237	    const grenze = Date.now() - 30 * 86400e3;
238	    db.sitzungen = db.sitzungen.filter((x) => !((x.widerrufenAm && new Date(x.widerrufenAm).getTime() < grenze) || new Date(x.ablauf).getTime() < grenze));
239	    const aktive = db.sitzungen.filter((x) => sitzungGueltig(x, u)).sort((a, b) => a.letzteAktivitaet.localeCompare(b.letzteAktivitaet));
240	    for (const x of aktive.slice(0, Math.max(0, aktive.length - 30))) {
241	      x.widerrufenAm = jetzt();
242	      x.widerrufenGrund = "grenze";
243	    }
244	
245	    u.letzterLogin = jetzt();
246	    historie(db, { nutzer: u, ok: true, methode: `${methode}${zweiFaktor ? " + 2FA" : ""}`, ip, userAgent, land });
247	    if (!bekannt && !["registrierung"].includes(methode)) {
248	      sicherheitMelden(db, u, {
249	        titel: "Anmeldung von einem neuen Gerät",
250	        text: `${g.label} · ${ort || "Ort unbekannt"}`,
251	        betreff: "Neue Anmeldung bei Ihrem Konto – ÖkoInvest",
252	        mailText: `Ihr Konto im Portal von ÖkoInvest wurde soeben von einem neuen Gerät verwendet: ${g.label}, ${ort || "Ort unbekannt"}. Wenn Sie das waren, ist nichts zu tun.`,
253	      });
254	    }
255	    if (methode !== "passwort" || zweiFaktor) internSicherheit.protokoll(db, u, "login", "nutzer", u.id, `Anmeldung (${methode}${zweiFaktor ? ", 2FA" : ""}) · ${g.label}`, ip);
256	    return { sitzung: { id: s.id }, geraetToken: neuesToken, neuesGeraet: !bekannt };
257	  });
258	}
259	
260	/** Aktive Sitzungen des Kontos (aktuelle markiert) */
261	export async function sitzungen(n) {
262	  if (!n) throw nichtAngemeldet();
263	  const db = sammlungen(await lesen());
264	  const u = nutzerById(db, n.id);
265	  return db.sitzungen
266	    .filter((s) => sitzungGueltig(s, u))
267	    .sort((a, b) => b.letzteAktivitaet.localeCompare(a.letzteAktivitaet))
268	    .map((s) => ({
269	      id: s.id, geraet: s.geraet, mobil: !!s.mobil, ort: s.ort, erstelltAm: s.erstelltAm, letzteAktivitaet: s.letzteAktivitaet, methode: s.methode,
270	      zweiFaktor: !!s.zweiFaktor, aktuell: s.id === n.sitzung?.id, organisation: s.organisationId ? db.organisationen.find((o) => o.id === s.organisationId)?.name || null : null,
271	    }));
272	}
273	
274	/**
275	 * Sitzung(en) beenden: { id } eine eigene Sitzung (auch die aktuelle = Abmelden) oder { alleAnderen: true }.
276	 * „Alle anderen“ erhöht zusätzlich die Sitzungsversion (beendet auch ältere Token) – die aktuelle Sitzung
277	 * übernimmt die neue Version; die Website setzt dafür ein neues Cookie.
278	 */
279	export async function sitzungBeenden(n, { id, alleAnderen = false } = {}) {
280	  if (!n) throw nichtAngemeldet();
281	  return aendern((db) => {
282	    sammlungen(db);
283	    const u = nutzerById(db, n.id);
284	    let beendet = 0;
285	    if (alleAnderen) {
286	      for (const s of db.sitzungen) {
287	        if (s.nutzerId !== u.id || s.id === n.sitzung?.id || s.widerrufenAm) continue;
288	        s.widerrufenAm = jetzt();
289	        s.widerrufenGrund = "abgemeldet";
290	        beendet++;
291	      }
292	      u.sitzungVersion = (u.sitzungVersion || 0) + 1;
293	      const aktuell = db.sitzungen.find((s) => s.id === n.sitzung?.id);
294	      if (aktuell) aktuell.version = u.sitzungVersion;
295	      internSicherheit.protokoll(db, u, "sitzung", "nutzer", u.id, `Alle anderen Sitzungen beendet (${beendet})`);
296	      return { beendet, sitzungVersion: u.sitzungVersion, nutzer: internSicherheit.ohneGeheimnis(u) };
297	    }
298	    const s = db.sitzungen.find((x) => x.id === v.kennung(id));
299	    if (!s || s.nutzerId !== u.id) throw nichtGefunden("Sitzung nicht gefunden.");
300	    if (!s.widerrufenAm) {
301	      s.widerrufenAm = jetzt();
302	      s.widerrufenGrund = s.id === n.sitzung?.id ? "abmeldung" : "abgemeldet";
303	      beendet = 1;
304	      if (s.id !== n.sitzung?.id) internSicherheit.protokoll(db, u, "sitzung", "nutzer", u.id, `Sitzung beendet: ${s.geraet}`);
305	    }
306	    return { beendet, sitzungVersion: u.sitzungVersion || 0 };
307	  });
308	}
309	
310	/** Anmeldehistorie inkl. Fehlversuchen (neueste zuerst) */
311	export async function anmeldungen(n, { limit = 50 } = {}) {
312	  if (!n) throw nichtAngemeldet();
313	  const db = sammlungen(await lesen());
314	  return db.anmeldungen
315	    .filter((a) => a.nutzerId === n.id)
316	    .slice(-Math.min(200, Math.max(1, Number(limit) || 50)))
317	    .reverse()
318	    .map(({ id, am, ok, methode, grund, ort, geraet }) => ({ id, am, ok, methode, grund, ort, geraet }));
319	}
320	
321	export async function geraete(n, { geraetToken = "" } = {}) {
322	  if (!n) throw nichtAngemeldet();
323	  const db = sammlungen(await lesen());
324	  const z = zf(db, n.id);
325	  const h = geraetToken ? sha256(String(geraetToken)) : "";
326	  return db.geraete
327	    .filter((g) => g.nutzerId === n.id)
328	    .sort((a, b) => b.letzteAnmeldung.localeCompare(a.letzteAnmeldung))
329	    .map((g) => ({
330	      id: g.id, label: g.label, mobil: !!g.mobil, ersteAnmeldung: g.ersteAnmeldung, letzteAnmeldung: g.letzteAnmeldung,
331	      vertraut: !!(z?.aktiv && g.vertrautBis && new Date(g.vertrautBis) > new Date() && g.zweiFaktorVersion === z.version),
332	      vertrautBis: g.vertrautBis, aktuell: !!h && g.hash === h,
333	    }));
334	}
335	
336	/** Gerät vergessen: Eintrag löschen (2FA wird dort wieder abgefragt, neue Anmeldung gilt als neues Gerät) */
337	export async function geraetVergessen(n, id) {
338	  if (!n) throw nichtAngemeldet();
339	  return aendern((db) => {
340	    sammlungen(db);
341	    const g = db.geraete.find((x) => x.id === v.kennung(id) && x.nutzerId === n.id);
342	    if (!g) throw nichtGefunden("Gerät nicht gefunden.");
343	    db.geraete = db.geraete.filter((x) => x.id !== g.id);
344	    internSicherheit.protokoll(db, n, "geraet", "nutzer", n.id, `Gerät vergessen: ${g.label}`);
345	    return { ok: true };
346	  });
347	}
348	
349	/** Ist das Gerät (Cookie) für die Zwei-Faktor-Anmeldung dieses Kontos gemerkt? */
350	export async function geraetVertraut({ nutzerId, geraetToken } = {}) {
351	  if (!nutzerId || !/^[A-Za-z0-9_-]{30,100}$/.test(String(geraetToken || ""))) return false;
352	  const db = sammlungen(await lesen());
353	  const z = zf(db, nutzerId);
354	  const g = db.geraete.find((x) => x.nutzerId === nutzerId && x.hash === sha256(geraetToken));
