339	   339	function einladungSuchen(db, token) {
340	   340	  const t = String(token || "");
341	   341	  if (!/^[A-Za-z0-9_-]{20,200}$/.test(t)) return null;
342	   342	  const h = sha256(t);
343	   343	  return (db.einladungen || []).find((x) => x.hash === h) || null;
344	   344	}
