346	   346	const maskieren = (email) => {
347	   347	  const [lokal, domain] = String(email).split("@");
348	   348	  return `${lokal.slice(0, 1)}${"•".repeat(Math.max(2, Math.min(6, lokal.length - 1)))}@${domain}`;
349	   349	};
