  1	// src/lib/plattform/organisation.js
  2	//
  3	// Firmenkonten (Organisationen & Teams) und Konto-Komfort – Stammlisten und Rechtematrix.
  4	// Client- und serverseitig nutzbar (keine Node-Importe). Frappe: plattform/konstanten.py (identisch).
  5	//
  6	// Rechte je Teamrolle (gelten für Objekte der Organisation: Flächen, Projekte, Interessen, Suchprofil):
  7	//   lesen     – sehen (Listen im Organisationskontext, Detailseiten, Nachrichten, Dokumente, Datenraum nach NDA)
  8	//   mitglied  – zusätzlich bearbeiten, Statusschritte als Eigentümer, hochladen, Nachrichten senden, anlegen
  9	//   admin     – zusätzlich Mitglieder einladen/entfernen, Rollen bis „Admin“ vergeben, Stammdaten ändern
 10	//   inhaber   – zusätzlich Inhaberschaft übertragen, Organisation löschen (genau ein Inhaber)
 11	
 12	export const ORGANISATION_ARTEN = {
 13	  investmenthaus: { label: "Investmenthaus / Investor", text: "Projekte prüfen, NDA und Datenraum im Team, gemeinsames Suchprofil." },
 14	  projektentwickler: { label: "Projektentwickler", text: "Projekte gemeinsam in die Börse stellen und Interessenten betreuen." },
 15	  stadtwerk: { label: "Stadtwerk / Kommune", text: "Flächen, Projekte und Beteiligungsmodelle im Team verfolgen." },
 16	  betrieb: { label: "Betrieb / Unternehmen", text: "Flächen, Anfragen und Unterlagen des Betriebs an einem Ort." },
 17	};
 18	export const ORGANISATION_ART_IDS = Object.keys(ORGANISATION_ARTEN);
 19	
 20	export const TEAM_ROLLEN = {
 21	  inhaber: { label: "Inhaber", stufe: 4, text: "Volle Rechte, überträgt die Inhaberschaft, löscht die Organisation." },
 22	  admin: { label: "Admin", stufe: 3, text: "Verwaltet Mitglieder und Einladungen, bearbeitet alles." },
 23	  mitglied: { label: "Mitglied", stufe: 2, text: "Sieht und bearbeitet die Objekte der Organisation." },
 24	  lesen: { label: "Nur lesen", stufe: 1, text: "Sieht die Objekte der Organisation, ändert nichts." },
 25	};
