 29	
 30	export const teamStufe = (rolle) => TEAM_ROLLEN[rolle]?.stufe || 0;
 31	export const darfTeamLesen = (rolle) => teamStufe(rolle) >= 1;
 32	export const darfTeamSchreiben = (rolle) => teamStufe(rolle) >= 2;
 33	export const darfTeamVerwalten = (rolle) => teamStufe(rolle) >= 3;
 34	export const teamRolleLabel = (r) => TEAM_ROLLEN[r]?.label || r;
