 97	export function base32(buf) {
 98	  let bits = 0;
 99	  let wert = 0;
100	  let out = "";
101	  for (const byte of buf) {
102	    wert = (wert << 8) | byte;
103	    bits += 8;
104	    while (bits >= 5) {
105	      out += B32[(wert >>> (bits - 5)) & 31];
106	      bits -= 5;
107	    }
108	  }
109	  if (bits > 0) out += B32[(wert << (5 - bits)) & 31];
110	  return out;
111	}
112	
113	export function base32Lesen(s) {
114	  const sauber = String(s || "").toUpperCase().replace(/[\s=-]/g, "");
115	  let bits = 0;
116	  let wert = 0;
117	  const out = [];
118	  for (const z of sauber) {
119	    const i = B32.indexOf(z);
120	    if (i < 0) throw new Error("Ungültiges Base32");
121	    wert = (wert << 5) | i;
122	    bits += 5;
123	    if (bits >= 8) {
124	      out.push((wert >>> (bits - 8)) & 255);
125	      bits -= 8;
126	    }
127	  }
128	  return Buffer.from(out);
129	}
