134	/** HOTP-Wert (RFC 4226) für Zähler `zaehler` */
135	export function hotp(schluessel, zaehler, stellen = STELLEN, algo = "sha1") {
136	  const b = Buffer.alloc(8);
137	  b.writeBigUInt64BE(BigInt(zaehler));
138	  const h = createHmac(algo, schluessel).update(b).digest();
139	  const o = h[h.length - 1] & 0x0f;
140	  const bin = ((h[o] & 0x7f) << 24) | (h[o + 1] << 16) | (h[o + 2] << 8) | h[o + 3];
141	  return String(bin % 10 ** stellen).padStart(stellen, "0");
142	}
