146	/** TOTP-Code eines Base32-Schlüssels zu einem Zeitpunkt (für Tests und Anzeige) */
147	export const totp = (geheimnisB32, zeitMs = Date.now()) => hotp(base32Lesen(geheimnisB32), zeitschritt(zeitMs));
