155	/**
156	 * Code prüfen. Liefert den Zeitschritt des passenden Codes oder null.
157	 * Nur Schritte > `letzterSchritt` zählen (derselbe Code ist nie zweimal gültig).
158	 */
159	export function totpPruefen(geheimnisB32, code, { letzterSchritt = -1, zeitMs = Date.now(), fenster = FENSTER } = {}) {
160	  const c = String(code || "").replace(/\s/g, "");
161	  if (!/^\d{6}$/.test(c) || !geheimnisB32) return null;
162	  const schluessel = base32Lesen(geheimnisB32);
163	  const jetzt = zeitschritt(zeitMs);
164	  let treffer = null;
165	  // alle Fenster-Schritte rechnen (gleiche Laufzeit, unabhängig vom Treffer)
166	  for (let d = -fenster; d <= fenster; d++) {
167	    const s = jetzt + d;
168	    if (gleich(hotp(schluessel, s), c) && s > letzterSchritt && treffer === null) treffer = s;
169	  }
