207	/** Text → "v1.<iv>.<tag>.<chiffrat>" (base64url) */
208	export function verschluesseln(text) {
209	  const iv = randomBytes(12);
210	  const c = createCipheriv("aes-256-gcm", schluesselMaterial(), iv);
211	  const ct = Buffer.concat([c.update(String(text), "utf8"), c.final()]);
212	  return ["v1", iv.toString("base64url"), c.getAuthTag().toString("base64url"), ct.toString("base64url")].join(".");
