215	export function entschluesseln(wert) {
216	  const [v, iv, tag, ct] = String(wert || "").split(".");
217	  if (v !== "v1" || !iv || !tag || !ct) return "";
218	  try {
219	    const d = createDecipheriv("aes-256-gcm", schluesselMaterial(), Buffer.from(iv, "base64url"));
220	    d.setAuthTag(Buffer.from(tag, "base64url"));
221	    return Buffer.concat([d.update(Buffer.from(ct, "base64url")), d.final()]).toString("utf8");
222	  } catch {
223	    return "";
224	  }
225	}
