260	/** IP gekürzt: 203.0.113.17 → 203.0.113.x · 2001:db8:1:2::5 → 2001:db8:1::/48 */
261	export function ipGrob(ip = "") {
262	  const s = String(ip || "").trim();
263	  if (!s) return "";
264	  if (/^\d+\.\d+\.\d+\.\d+$/.test(s)) return s.replace(/\.\d+$/, ".x");
265	  if (s.includes(":")) {
266	    const teile = s.split(":").filter(Boolean).slice(0, 3);
267	    return `${teile.join(":")}::/48`;
268	  }
269	  return "";
270	}
